add_action( 'woocommerce_variation_options_pricing', 'perfectpixel_variation_field_input', 10, 3 );
add_action( 'woocommerce_save_product_variation', 'perfectpixel_variation_field_save', 10, 2 );
add_filter( 'woocommerce_available_variation', 'perfectpixel_variation_field_display', 10, 3 );

function perfectpixel_variation_field_input( $loop, $variation_data, $variation ) {
	woocommerce_wp_text_input(
		array(
			'id'            => 'perfectpixel_variation_field[' . $loop . ']',
			'label'         => '{{variation_field_label}}',
			'value'         => get_post_meta( $variation->ID, '_perfectpixel_variation_field', true ),
			'wrapper_class' => 'form-row form-row-full',
		)
	);
}

function perfectpixel_variation_field_save( $variation_id, $loop ) {
	if ( isset( $_POST['perfectpixel_variation_field'][ $loop ] ) ) {
		update_post_meta( $variation_id, '_perfectpixel_variation_field', sanitize_text_field( wp_unslash( $_POST['perfectpixel_variation_field'][ $loop ] ) ) );
	}
}

// Appended to the variation description, which WooCommerce already shows on selection.
function perfectpixel_variation_field_display( $data, $product, $variation ) {
	$value = get_post_meta( $variation->get_id(), '_perfectpixel_variation_field', true );
	if ( '' !== (string) $value ) {
		$data['variation_description'] .= '<p class="perfectpixel-variation-field"><strong>' . esc_html( '{{variation_field_label}}' ) . ':</strong> ' . esc_html( $value ) . '</p>';
	}
	return $data;
}
